// @category GFZ
import ghidra.app.script.GhidraScript;import ghidra.program.model.listing.*;import java.util.*;import java.io.*;import java.nio.charset.StandardCharsets;
public class ReportV121Coverage extends GhidraScript{
 public void run()throws Exception{String[]a=getScriptArgs();String out=a.length>0?a[0]:null;FunctionIterator it=currentProgram.getFunctionManager().getFunctions(true);int internal=0,own=0,fn=0,dom=0,over=0,un=0;Map<String,Integer>dc=new TreeMap<>();ArrayList<String>urs=new ArrayList<>();while(it.hasNext()){Function f=it.next();if(f.isExternal())continue;internal++;int oc=0,dd=0;boolean fin=false;for(FunctionTag t:f.getTags()){String n=t.getName();if(n.startsWith("GFZ.V120.PrimaryOwner.")){oc++;}if(n.equals("GFZ.V120.FinalNoPrimaryOwner"))fin=true;if(n.startsWith("GFZ.V121.CodeDomain.")){dd++;dc.merge(n.substring("GFZ.V121.CodeDomain.".length()),1,Integer::sum);}}if(oc>0)own++;if(fin)fn++;if(dd>0)dom++;if((oc>0?1:0)+(fin?1:0)+(dd>0?1:0)>1)over++;if(oc==0&&!fin&&dd==0){un++;urs.add(String.format("%08X\t%s\t%d",f.getEntryPoint().getOffset(),f.getName(),f.getBody().getNumAddresses()));}}
 String sum="V121_COVERAGE internal="+internal+" owner="+own+" finalNo="+fn+" codeDomain="+dom+" overlap="+over+" explicit="+(own+fn+dom)+" unresolved="+un+" pct="+String.format(Locale.ROOT,"%.5f",100.0*(own+fn+dom)/internal);println(sum);println("DOMAINS="+dc);if(out!=null)try(PrintWriter w=new PrintWriter(new OutputStreamWriter(new FileOutputStream(out),StandardCharsets.UTF_8))){w.println(sum);for(Map.Entry<String,Integer>e:dc.entrySet())w.println(e.getValue()+"\t"+e.getKey());w.println("--UNRESOLVED--");for(String s:urs)w.println(s);}}
}
